package com.edtech.platform.booking;
import com.edtech.platform.common.AbstractIntegrationTest; import com.edtech.platform.booking.repository.SessionReportRepository; import org.junit.jupiter.api.Test; import org.springframework.beans.factory.annotation.Autowired; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.data.domain.PageRequest; import java.time.Instant; import java.util.UUID; import static org.assertj.core.api.Assertions.assertThat;
class StudentSessionReportPersistenceIT extends AbstractIntegrationTest { @Autowired JdbcTemplate jdbc; @Autowired SessionReportRepository reports;
 @Test void reportsAreOwnedByStudentAndPaged(){UUID s1=UUID.randomUUID(),s2=UUID.randomUUID(),t=UUID.randomUUID(),sub=UUID.randomUUID(),b1=UUID.randomUUID(),b2=UUID.randomUUID(),r1=UUID.randomUUID(),r2=UUID.randomUUID(); Instant now=Instant.now(); java.sql.Timestamp ts=java.sql.Timestamp.from(now); jdbc.update("insert into users(id,email,password_hash,full_name,role,status) values(?,?,?,?,?,?)",s1,s1+"@t","h","S1","STUDENT","ACTIVE"); jdbc.update("insert into users(id,email,password_hash,full_name,role,status) values(?,?,?,?,?,?)",s2,s2+"@t","h","S2","STUDENT","ACTIVE"); jdbc.update("insert into teacher_profiles(id,user_id,profile_status) values(?,?,?)",t,s1,"APPROVED"); jdbc.update("insert into subjects(id,code,name,slug) values(?,?,?,?)",sub,"C"+sub,"Sub","sub"+sub); jdbc.update("insert into bookings(id,teacher_id,student_id,subject_id,start_time,end_time,delivery_mode,status,is_trial,outside_availability_warning,settlement_processed,version,created_at,updated_at,is_deleted) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",b1,t,s1,sub,java.sql.Timestamp.from(now.minusSeconds(120)),java.sql.Timestamp.from(now.minusSeconds(60)),"ONLINE","COMPLETED",true,false,false,0,ts,ts,false); jdbc.update("insert into bookings(id,teacher_id,student_id,subject_id,start_time,end_time,delivery_mode,status,is_trial,outside_availability_warning,settlement_processed,version,created_at,updated_at,is_deleted) values(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",b2,t,s2,sub,java.sql.Timestamp.from(now.minusSeconds(120)),java.sql.Timestamp.from(now.minusSeconds(60)),"ONLINE","COMPLETED",true,false,false,0,ts,ts,false); jdbc.update("insert into session_reports(id,booking_id,content,teacher_self_rating,created_at,updated_at,is_deleted) values(?,?,?,?,?,?,?)",r1,b1,"ok",5,now,now,false); jdbc.update("insert into session_reports(id,booking_id,content,teacher_self_rating,created_at,updated_at,is_deleted) values(?,?,?,?,?,?,?)",r2,b2,"hidden",5,now,now,false); assertThat(reports.findByStudentId(s1,PageRequest.of(0,20))).hasSize(1).allMatch(x->x.getBookingId().equals(b1)); }
}
